  function focusWin(win){if(!win)return;qa(".window").forEach(w=>w.classList.remove("active-window"));win.classList.remove("minimized");win.style.zIndex=String(++z);win.classList.add("active-window");activeWindow=win;qa(".taskbar-app").forEach(b=>b.classList.toggle("active",b.dataset.window===win.id))}
